CREATE OR REPLACE FUNCTION calculate_size_compatibility(donor_reg_id TEXT, recip_reg_id TEXT)
RETURNS REAL AS $$
DECLARE
    donor_bmi REAL;
    recipient_bmi REAL;
    size_score REAL;
BEGIN
    -- Retrieve donor's BMI from the JSONB field
    SELECT CAST(d."physicalstats"->>'Bmi_Value' AS REAL) INTO donor_bmi
    FROM demographics d
    WHERE d."contrib_registry" = donor_reg_id;

    -- Retrieve recipient's BMI from the dedicated column
    SELECT rd."bmi_val" INTO recipient_bmi
    FROM recipients_demographics rd
    WHERE rd."recip_registry" = recip_reg_id;

    -- Check for NULL or zero values to prevent errors
    IF donor_bmi IS NULL OR recipient_bmi IS NULL OR recipient_bmi = 0 THEN
        RETURN NULL;
    END IF;

    -- Calculate the Size Compatibility Score using the knowledge base formula
    size_score := 1 - ABS((donor_bmi / recipient_bmi) - 1);

    RETURN size_score;
END;
$$ LANGUAGE plpgsql;

