CREATE OR REPLACE FUNCTION get_donor_renal_score(p_donor_id TEXT)
RETURNS REAL AS $$
DECLARE
    v_creatinine REAL;
    v_age REAL;
    v_egfr REAL;
    v_renal_score REAL;
BEGIN
    -- Retrieve donor's age and serum creatinine
    SELECT 
        CAST(regexp_replace(d.age_count, '[^0-9.]', '', 'g') AS REAL),
        CAST(regexp_replace(fr.don_crtn_val, '[^0-9.]', '', 'g') AS REAL)
    INTO v_age, v_creatinine
    FROM demographics d
    JOIN function_and_recovery fr ON d."contrib_registry" = fr."recov_don_registry"
    WHERE d."contrib_registry" = p_donor_id;

    -- Return NULL if data is missing
    IF v_age IS NULL OR v_creatinine IS NULL OR v_creatinine = 0 THEN
        RETURN NULL;
    END IF;

    -- Calculate eGFR using the simplified formula for males
    v_egfr := 141 * POWER((v_creatinine / 0.9), -0.411) * POWER(0.993, v_age);

    -- Calculate Renal Function Score with specified weights
    v_renal_score := (0.8 * v_egfr) - (0.2 * v_creatinine);

    RETURN v_renal_score;
END;
$$ LANGUAGE plpgsql;

