CREATE OR REPLACE FUNCTION calculate_composite_allocation_score(p_match_id TEXT)
RETURNS REAL AS $$
DECLARE
    v_urgency_score REAL;
    v_immune_score REAL;
    v_egs_score REAL;
    v_final_score REAL;
    v_recip_id TEXT;
    v_donor_id TEXT;
    v_med_urgency TEXT;
    v_wait_time TEXT;
    v_blood_compat TEXT;
    v_hla_mismatch INT;
    v_donor_age TEXT;
BEGIN
    SELECT 
        tm.recip_ref_reg, tm.donor_ref_reg, c.med_urgency, c.wait_time, 
        cm.blood_compat, cm.hla_mis_count, d.age_count
    INTO 
        v_recip_id, v_donor_id, v_med_urgency, v_wait_time, 
        v_blood_compat, v_hla_mismatch, v_donor_age
    FROM transplant_matching tm
    JOIN clinical c ON tm.recip_ref_reg = c.clin_recip_registry
    JOIN compatibility_metrics cm ON tm.match_rec_registry = cm.match_comp_registry
    JOIN demographics d ON tm.donor_ref_reg = d.contrib_registry
    WHERE tm.match_rec_registry = p_match_id;

    IF NOT FOUND THEN RETURN NULL; END IF;

    v_urgency_score := (0.7 * 
        CASE v_med_urgency 
            WHEN 'Status 1A' THEN 5 WHEN 'Status 1B' THEN 4 ELSE 2 
        END) + 
        (0.3 * (CAST(regexp_replace(v_wait_time, '[^0-9.]', '', 'g') AS REAL) / 365.0));

    v_immune_score := (0.6 * CASE WHEN LOWER(v_blood_compat) = 'compatible' THEN 1 ELSE 0 END) + 
                      (0.4 * (1 - (v_hla_mismatch / 6.0)));

    v_egs_score := 1 / (1 + exp(-(-0.5 + 1.5 * v_immune_score - 0.02 * CAST(regexp_replace(v_donor_age, '[^0-9]', '', 'g') AS REAL))));

    v_final_score := (0.5 * v_urgency_score) + (0.25 * v_immune_score) + (0.25 * v_egs_score);

    RETURN v_final_score;
END;
$$ LANGUAGE plpgsql;

