CREATE OR REPLACE FUNCTION update_center_performance_summary()
RETURNS TRIGGER AS $$
DECLARE
    v_center_id TEXT;
    v_egs_val REAL;
    v_current_total BIGINT;
    v_current_avg REAL;
BEGIN
    -- Only act when a match is newly marked as 'Completed'
    IF NEW.match_status = 'Completed' AND OLD.match_status != 'Completed' THEN
        -- Get the center ID and EGS score for this match
        SELECT ar.tx_cen_code, re.egs_val
        INTO v_center_id, v_egs_val
        FROM administrative_and_review ar
        JOIN risk_evaluation re ON ar.adm_rev_registry = re.risk_eval_registry
        WHERE ar.adm_rev_registry = NEW.match_rec_registry;

        IF v_center_id IS NOT NULL AND v_egs_val IS NOT NULL THEN
            -- UPSERT logic for the summary table
            INSERT INTO center_performance_live (center_id, total_transplants, avg_egs_score)
            VALUES (v_center_id, 1, v_egs_val)
            ON CONFLICT (center_id) DO UPDATE
            SET 
                total_transplants = center_performance_live.total_transplants + 1,
                -- Recalculate the running average
                avg_egs_score = ((center_performance_live.avg_egs_score * center_performance_live.total_transplants) + v_egs_val) / (center_performance_live.total_transplants + 1);
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

