        WHEN 'Low' THEN v_engagement_score := 1;
        ELSE v_engagement_score := 0; -- Default case for NULL or other unexpected values
    END CASE;

    -- Step 4: Return the calculated score.
    RETURN v_engagement_score;

-- Add exception handling for robustness in case of unexpected errors.
EXCEPTION
    WHEN others THEN
        RAISE WARNING 'Error calculating TES for tx_key %: %', p_tx_key, SQLERRM;
        RETURN NULL;
END;
